import type { TroubleCodeGuide } from "./trouble-code-data";

const manuals={label:"Toyota 4Runner manuals and warranty guides",url:"https://www.toyota.com/owners/warranty-owners-manuals/",note:"Official Toyota model-year lookup; confirm VIN, engine, drivetrain and emissions certification"};
const tis={label:"Toyota Technical Information System",url:"https://techinfo.toyota.com/",note:"Toyota's current North American repair manuals, wiring diagrams, bulletins and calibration information"};
const fuelTsb={label:"Toyota T-SB-0009-23 — fuel-pump pressure loss",url:"https://static.nhtsa.gov/odi/tsbs/2023/MC-10235216-9999.pdf",note:"Includes 2014–2019 4Runner among specifically listed applications; VIN/VDS and program eligibility must be confirmed"};
const evapTsb={label:"Toyota T-SB-0030-10 — 2005–2009 4Runner P0455/P0441/P0456",url:"https://charm.li/Toyota/2005/4%20Runner%202WD%20V6-4.0L%20%281GR-FE%29/Repair%20and%20Diagnosis/Technical%20Service%20Bulletins/Customer%20Interest/Fuel%20System%20-%20MIL%20ON%2FDTC%27s%20P0441%2FP0455%2FP0456/",note:"2005–2009 4Runner only; applies to P0455 plus P0441, or P0456, and explicitly excludes P0441 alone"};
const oldLean={label:"Toyota 2002 4Runner 5VZ-FE P0171 diagnostic procedure",url:"https://www.toyota-4runner.org/attachments/3rd-gen-t4rs/146663d1424410405-introduced-p0171-changing-upstream-air-fuel-ratio-sensor-cip0171p-pdf",note:"Historical 5VZ-FE repair-manual procedure listing induction, injector, MAF, coolant, fuel-pressure, exhaust, A/F sensor and PCV checks"};
const oldThermostat={label:"Toyota 2002 4Runner 5VZ-FE P0128 diagnostic procedure",url:"https://www.toyota-4runner.org/attachments/3rd-gen-t4rs/145120d1423199799-1999-t4r-trouble-code-help-please-05-diagnostics-pdf",note:"Historical 5VZ-FE procedure: cold start and sufficient warm-up with coolant still below 75°C/167°F; check thermostat, cooling system and ECT signal"};
const currentP0128={label:"Toyota 2011 4Runner 1GR-FE P0128 procedure",url:"https://charm.li/Toyota/2011/4%20Runner%204WD%20V6-4.0L%20%281GR-FE%29/Repair%20and%20Diagnosis/A%20L%20L%20%20Diagnostic%20Trouble%20Codes%20%28%20DTC%20%29/Testing%20and%20Inspection/P%20Code%20Charts/P0128/",note:"1GR-FE monitor description comparing estimated warm-up with actual coolant temperature"};
const oldP1604={label:"Toyota 2010 4Runner 1GR-FE P1604 description",url:"https://lemon-manuals.org.ua/Toyota/2010/4Runner%20Limited%2C%20RWD/Repair%20and%20Diagnosis%20%28Single%20Page%29/Engine%20Performance/Testing%20%26%20Diagnosis/Engine%20Control%20%28SFI%29%20System%20%281GR-FE%29%20%28Diagnostic%20Codes%20%28P1604-P2610%29%20%26%20Circuit%20Tests%29/SFI%20System/DTC%20P1604%3A%20Startability%20Malfunction/Description/",note:"Defines the startability event and lists battery, fuel, ignition, immobilizer, sensors, air and mechanical causes"};

const vehicle={name:"Toyota 4Runner",kicker:"TOYOTA 4RUNNER · ENGINE AND EMISSIONS DIAGNOSTICS",breadcrumb:"Toyota 4Runner",about:"Toyota 4Runner engine and emissions diagnostics",yearsIntro:"U.S.-market 4Runner diagnostics span the 1996–2002 3RZ-FE four-cylinder and 5VZ-FE V6, the 2003–2009 1GR-FE V6 and optional 2UZ-FE V8, the long-running 2010–2024 1GR-FE V6, and the 2025+ turbocharged 2.4L powertrains including i-FORCE MAX. Bank layout, fuel and EVAP hardware, VVT strategy and monitor logic differ. Off-road dust, water crossings, skid-plate work, auxiliary wiring and modified intakes add failure paths that sedan-oriented guides often miss. Confirm VIN, model year, engine, emissions label and modifications before testing."};
type Input=Omit<TroubleCodeGuide,"slug"|"vehicle">&{slug:string};
const article=(x:Input):TroubleCodeGuide=>({...x,slug:`toyota/4runner/${x.slug}`,vehicle});

export const troubleCode4Runner:TroubleCodeGuide[]=[
article({slug:"p0420",code:"P0420",title:"P0420 Code Toyota 4Runner: Bank 1 Catalyst Diagnosis",description:"Diagnose 4Runner P0420 by identifying Bank 1, checking misfire, trims, oil use, trail damage, exhaust leaks and sensor response before replacing the catalyst.",definition:"Catalyst System Efficiency Below Threshold (Bank 1)",severity:"Service soon",driveAdvice:"A steady P0420 with normal power usually permits a short diagnostic trip. Avoid towing, steep grades and heavy throttle until misfire and exhaust restriction are excluded. Stop if the lamp flashes, the engine shakes, power collapses, the converter glows or raw-fuel odor is present; continued load can melt the catalyst.",quickAnswer:"P0420 means the ECM judged Bank 1 catalyst oxygen-storage performance below threshold. It does not identify the failed part or the reason performance declined. On a 4Runner, first save misfire and fuel-trim history, check oil/coolant consumption, inspect the exhaust and shields for trail or skid-plate damage, and graph the upstream A/F and downstream O2 signals using the engine-specific Toyota procedure. V6 and V8 trucks have two banks, while older four-cylinder 4Runners have one. Do not apply the Highlander's early 2AZ-FE calibration bulletin or a bulletin found for another Toyota—the 4Runner and its engine must appear in applicability.",symptoms:[{key:"normal",label:"MIL on, truck feels normal",response:"Preserve monitor data and test prerequisites before ordering a converter."},{key:"flash",label:"MIL flashes on a climb or tow",response:"Reduce load and stop sustained driving; correct the misfire first."},{key:"rattle",label:"Rattle after trail contact",response:"Inspect shields, pipe impact and substrate damage; test restriction if power is low."},{key:"repeat",label:"P0420 returned after replacement",response:"Audit the emissions application, exhaust sealing and upstream engine cause."}],causes:[{cause:"Bank 1 catalyst aged, contaminated or physically damaged",evidence:"All prerequisite tests pass and catalyst monitor fails",firstTest:"Toyota engine-specific storage/efficiency test"},{cause:"Misfire or rich running overheated substrate",evidence:"Flash event, history codes, deposits or abnormal trims",firstTest:"Repair ignition/fuel fault before catalyst work"},{cause:"Oil or coolant contamination",evidence:"Consumption, smoke, coolant loss or deposits",firstTest:"Mechanical and cooling-system diagnosis"},{cause:"Exhaust leak or trail-impact damage",evidence:"Cold tick, soot, dented pipe or failed leak test",firstTest:"Cold inspection and safe low-pressure leak test"},{cause:"A/F or downstream O2 circuit fault",evidence:"Controlled response or circuit measurement fails",firstTest:"Graph signals and test wiring"}],freezeFrame:["RPM, calculated load, vehicle speed and coolant temperature","Bank 1 and Bank 2 fuel trims where applicable","Misfire counters and historical codes","Upstream A/F and downstream O2 values","Oil/coolant use and towing history","Exhaust impact, leak, rattle and restriction evidence"],steps:[{title:"Save codes and readiness",detail:"Keep freeze frame, pending and permanent codes before any reset."},{title:"Identify engine and Bank 1",detail:"Use cylinder 1 and the exact service diagram; front/rear guesses vary by engine."},{title:"Eliminate upstream damage",detail:"Resolve misfire, rich/lean control and oil/coolant entry before catalyst judgment."},{title:"Inspect the complete exhaust",detail:"Look above skid plates and around joints, bungs and crushed sections when cold."},{title:"Compare sensor behavior",detail:"Use Toyota's specified monitor conditions; a rear sensor that switches is evidence, not a verdict."},{title:"Complete the catalyst monitor",detail:"After repair, verify no pending P0420 during an appropriate safe drive."}],dontReplace:"Do not replace the downstream sensor or converter from the code title. A trail-damaged pipe can leak, a misfire can destroy a new converter, and a wrong emissions-certification part may fit physically yet fail monitoring or legal requirements.",yearNotes:["1996–2002 four-cylinder/V6, 2003–2009 V6/V8 and 2010–2024 V6 layouts require different bank and sensor identification.","V6/V8 P0420 is Bank 1; P0430 is the corresponding Bank 2 catalyst code.","Lift kits and skid plates can hide exhaust contact or place stressed joints out of casual view.","2025+ turbo/hybrid monitor logic and exhaust packaging must be diagnosed from current VIN-specific information."],faqs:[{question:"Does P0420 always mean a bad converter?",answer:"No. Misfire, mixture, contamination, leaks and sensor circuits must be excluded."},{question:"Which side is Bank 1?",answer:"The bank containing cylinder 1; confirm the exact engine diagram rather than using a universal left/right answer."},{question:"Can off-road damage cause it?",answer:"Yes. Pipe dents, joint stress, sensor harness damage and leaks can affect catalyst diagnosis."},{question:"Can I keep towing?",answer:"Avoid it until active misfire and restriction are ruled out; load increases catalyst temperature."},{question:"Will a rear oxygen sensor fix it?",answer:"Only when response and circuit testing prove it faulty."},{question:"Can oil burning ruin a converter?",answer:"Yes. Oil ash can poison catalyst material, so repair the consumption source."},{question:"Why did a new converter not fix it?",answer:"An upstream fault, leak, incorrect part application or wiring problem may remain."},{question:"What proves repair?",answer:"Healthy engine control and a completed catalyst monitor without pending P0420."}],deepDive:[{heading:"Inspect where off-road protection hides the evidence",paragraphs:["A skid plate can conceal a flattened pipe, shiny contact point or soot at a stressed joint. Inspect the system cold with the vehicle safely supported.","Do not strike the converter to test it. Internal substrate can be damaged, and an impact sound does not measure flow capacity."]},{heading:"Bank comparison is useful on V6 and V8 trucks",paragraphs:["Compare trims, A/F response and downstream behavior between banks under the same load. A bank-specific difference can localize a leak, injector or sensor issue.","Nearly identical abnormal behavior on both banks moves shared fueling, air metering or contamination higher on the list."]},{heading:"Protect the replacement from the original cause",paragraphs:["Review the event that first illuminated the lamp—especially flashing under towing or a long climb. Historical misfire evidence may explain catalyst damage even if idle is now smooth.","Use the VIN and underhood label for emissions certification. Converter legality and monitor capacity cannot be established by flange shape alone."]}],sources:[manuals,tis]}),

article({slug:"p0171",code:"P0171",title:"P0171 Code Toyota 4Runner: Bank 1 Lean Diagnosis",description:"Diagnose 4Runner P0171 using bank-to-bank fuel trims, intake/MAF inspection and measured fuel pressure, including the exact 2014–2019 Toyota pump bulletin.",definition:"System Too Lean (Bank 1)",severity:"Diagnose promptly",driveAdvice:"Limit driving if the 4Runner hesitates, stalls or shows strongly positive trims, and avoid towing or hard climbs. Stop for a flashing lamp, detonation, severe power loss or fuel-pressure failure. A smooth-running vehicle with a steady lamp can usually make a short diagnostic trip while data is captured.",quickAnswer:"P0171 means the ECM added more fuel than its Bank 1 correction limit; it does not say the Bank 1 A/F sensor failed. Compare both banks at idle, 2,500 rpm and controlled load. Equal lean correction points toward a shared post-MAF leak, MAF under-reporting or weak fuel delivery. A Bank 1-only problem favors that bank's intake seal, exhaust leak, injector or sensor circuit. Dusty filters, cracked intake bellows, modified snorkels and PCV hoses deserve inspection on trail-used trucks. Toyota T-SB-0009-23 includes specified 2014–2019 4Runners in its loss-of-fuel-pressure program, but pressure must be tested and VIN/VDS eligibility confirmed.",symptoms:[{key:"idle",label:"Rough mainly at idle",response:"Compare trims at raised rpm and smoke-test intake/PCV/purge paths."},{key:"load",label:"Hesitates on hills or towing",response:"Graph fuel pressure and MAF under demand; stop if pressure collapses."},{key:"both",label:"P0171 and P0174 together",response:"Prioritize shared measured-air and fuel-supply causes."},{key:"dust",label:"Code followed dusty trail use or intake work",response:"Inspect filter sealing, MAF contamination, clamps, snorkel joints and duct cracks."}],causes:[{cause:"Post-MAF air leak or PCV/purge leak",evidence:"Trims highest at idle and improve with rpm",firstTest:"Regulated smoke test"},{cause:"MAF under-reporting from contamination or intake alteration",evidence:"Both banks lean and airflow implausible for load",firstTest:"Inspect intake and compare MAF/load data"},{cause:"Low fuel pressure or volume",evidence:"Lean worsens under load, hard start or P0087",firstTest:"Pressure test during the fault"},{cause:"Bank 1 injector imbalance or intake gasket leak",evidence:"Bank split and contribution difference",firstTest:"Bank-localized smoke/injector balance test"},{cause:"Bank 1 exhaust leak or A/F circuit issue",evidence:"Cold tick/soot or failed circuit response",firstTest:"Exhaust leak and sensor circuit testing"}],freezeFrame:["Short- and long-term trims for both banks","RPM, load, speed and coolant temperature","MAF airflow and calculated load","Commanded/actual fuel pressure where available","A/F sensor data and misfire counts","Air filter, snorkel/intake modification and trail history"],steps:[{title:"Keep the two-bank pattern",detail:"Save data before clearing learned corrections or cleaning the MAF."},{title:"Inspect measured-air integrity",detail:"Check filter seat, air-box clips, bellows, clamps, PCV and aftermarket intake joints."},{title:"Compare idle with raised rpm",detail:"A vacuum leak usually has proportionally more effect at idle."},{title:"Measure fuel delivery under demand",detail:"Apply the Toyota pump bulletin only after VIN/application and pressure evidence agree."},{title:"Localize a Bank 1-only fault",detail:"Test that bank's exhaust, intake sealing and injector contribution."},{title:"Verify in the original terrain/load condition",detail:"Use a safe road test and confirm both trims remain controlled with no pending code."}],dontReplace:"Do not replace the Bank 1 A/F sensor because P0171 says Bank 1. The sensor may be accurately reporting extra air or insufficient fuel. Do not replace a pump solely because a 2014–2019 4Runner appears in T-SB-0009-23; confirm exact eligibility and pressure loss.",yearNotes:["The 2002 5VZ-FE Toyota procedure lists induction, MAF, injectors, fuel pressure, exhaust leakage, PCV and A/F sensor checks rather than a one-part fix.","2014–2019 4Runner appears in T-SB-0009-23's defined fuel-pump applications.","The 2003–2009 optional 2UZ-FE V8 and 1GR-FE V6 do not share all intake and bank-access details.","2025+ turbo engines add charge-air plumbing and pressure data to lean diagnosis."],faqs:[{question:"Does P0171 mean a bad A/F sensor?",answer:"No. The sensor can correctly report a lean mixture caused by air, fuel, exhaust or injector faults."},{question:"What does P0171 plus P0174 suggest?",answer:"Both banks lean makes shared intake, MAF and fuel-delivery causes more likely."},{question:"Can a dirty filter cause it?",answer:"Restriction or poor sealing can affect airflow; inspect data and the whole intake rather than assuming."},{question:"Can a snorkel cause P0171?",answer:"A leak, poor MAF housing geometry or unsealed joint in a modified intake can influence measurement."},{question:"Is the fuel pump automatically covered?",answer:"No. The Toyota program has year, VIN/VDS and other eligibility requirements."},{question:"Can I clean the MAF?",answer:"Only after recording data; use an approved method and never touch the sensing element."},{question:"Can a gas cap cause P0171?",answer:"A cap mainly affects EVAP sealing; a purge valve leaking into the intake is more relevant to fuel trim."},{question:"What confirms repair?",answer:"Balanced, controlled trims at idle and load with normal pressure and no pending P0171."}],deepDive:[{heading:"Trail dust changes the intake inspection",paragraphs:["Look downstream of the filter for dust tracks. A poor air-box seal can contaminate the MAF and admit abrasive material even when clamps appear tight.","Check flexible bellows from below and while gently moving them. Cracks can close at rest and open as the engine twists under load."]},{heading:"Bank split prevents system-wide guesswork",paragraphs:["On a V engine, one-bank correction points away from a shared MAF more than equal correction does. Use the comparison before removing hard-to-access components.","A cold exhaust leak upstream of Bank 1's sensor can introduce oxygen and mimic lean combustion; soot and a cold tick are useful clues."]},{heading:"Pressure at idle may miss the pump failure",paragraphs:["A marginal pump can satisfy idle demand and fall behind on a grade. Graph pressure against load and reproduce the freeze-frame condition safely.","T-SB-0009-23 supports this branch for exact 2014–2019 applications, but a listed vehicle still requires the bulletin's confirmation process."]}],sources:[oldLean,fuelTsb,manuals,tis]}),

article({slug:"p0441",code:"P0441",title:"P0441 Code Toyota 4Runner: Test EVAP Purge Flow",description:"Diagnose 4Runner P0441 with purge, vent, cap, hose and tank-pressure tests, plus the exact limit of Toyota's 2005–2009 combined-code bulletin.",definition:"Evaporative Emission Control System Incorrect Purge Flow",severity:"Service soon",driveAdvice:"P0441 alone usually allows a short trip if the 4Runner runs normally and there is no fuel odor or wetness. Stop and park outdoors for strong vapor odor, visible fuel, damaged tank/lines or refueling spit-back. Keep sparks, smoking and unapproved pressure sources away from the EVAP system.",quickAnswer:"P0441 means the commanded EVAP purge test did not create the expected tank-pressure response. Too little purge, unintended purge, an open leak, a restricted vent or biased pressure data can all produce it. Save fuel level and companion codes before touching the cap. Test purge sealing when commanded off, commanded flow when on, vent closure and tank-pressure response, then smoke-test at approved low pressure. T-SB-0030-10 is often oversimplified online: it covers 2005–2009 4Runners with P0455 plus P0441, or P0456. Toyota explicitly says the bulletin does not apply when P0441 sets alone.",symptoms:[{key:"alone",label:"P0441 is the only EVAP code",response:"Use the repair manual; T-SB-0030-10 explicitly excludes this pattern."},{key:"combo",label:"P0441 plus P0455 on a 2005–2009",response:"Run Toyota's automatic EVAP check and cap/filler sealing branch."},{key:"fill",label:"Hard start after refueling",response:"Test whether the purge valve leaks vapor into the intake while closed."},{key:"trail",label:"Code followed underbody work or trail impact",response:"Inspect canister, rear hoses and connectors for disconnection, pinch or damage."}],causes:[{cause:"Purge valve leaking or failing to flow",evidence:"Vacuum/flow does not match command state",firstTest:"Closed-state and bidirectional flow test"},{cause:"System leak prevents purge vacuum",evidence:"Companion P0455/P0456 or smoke outlet",firstTest:"Regulated smoke test"},{cause:"Vent valve/canister restriction",evidence:"Poor vent command response or refueling problem",firstTest:"Valve command and flow test"},{cause:"Cap/filler sealing fault in exact combined-code case",evidence:"2005–2009 plus specified code combination and failed seal test",firstTest:"Follow T-SB-0030-10"},{cause:"Tank-pressure sensor/circuit bias",evidence:"Implausible or unresponsive pressure PID",firstTest:"Controlled pressure comparison"}],freezeFrame:["Fuel level, ambient temperature and soak time","Tank-pressure sensor value","Purge and vent command state","P0455/P0456/P0446 companion codes","Recent refueling and repeated topping-off","Tank, skid-plate, hitch or underbody service history"],steps:[{title:"Separate P0441 alone from a code combination",detail:"Bulletin eligibility changes immediately based on companion codes."},{title:"Inspect found condition",detail:"Record cap position and accessible hose damage before disturbing anything."},{title:"Test purge in both states",detail:"A click does not prove sealing or adequate flow."},{title:"Command vent and watch pressure",detail:"Use a capable scan tool with the correct generation's Toyota utility."},{title:"Smoke-test safely",detail:"Use regulated EVAP equipment; unregulated shop air can damage the tank or valves."},{title:"Run the monitor in its window",detail:"Fuel level, soak and temperature affect whether verification completes."}],dontReplace:"Do not replace the cap merely because you found T-SB-0030-10. For P0441 alone, Toyota says that bulletin does not apply. For the listed combined-code pattern, the cap/filler sealing area must still be tested.",yearNotes:["2005–2009: T-SB-0030-10 applies to P0455 with P0441, or P0456—not P0441 alone.","Third-generation systems and fifth-generation leak-detection hardware do not share every valve or monitor routine.","Rear skid plates, auxiliary tanks, hitch work and fuel-pump service can disturb EVAP routing.","Repeated topping-off can send liquid fuel into a canister designed for vapor."],faqs:[{question:"Is P0441 just a loose gas cap?",answer:"No. Purge, vent, hoses, canister, pressure sensing and system leaks can all affect purge flow."},{question:"Does Toyota's cap bulletin apply to P0441 alone?",answer:"No. T-SB-0030-10 explicitly directs normal diagnosis when P0441 is alone."},{question:"Can P0441 cause hard starting after filling?",answer:"Yes. A purge valve leaking vapor into the intake can upset the start mixture."},{question:"Can I drive?",answer:"Usually briefly if no fuel odor, wetness or drivability problem exists."},{question:"Can trail damage cause it?",answer:"Yes. Rear vapor hoses, canister parts and wiring can be damaged or disconnected."},{question:"Can overfilling matter?",answer:"Yes. Repeated topping-off can saturate the charcoal canister with liquid fuel."},{question:"Should I clear it before testing?",answer:"No. Save fuel level, pressure data and companion codes first."},{question:"What confirms repair?",answer:"Correct valve response and a completed EVAP monitor without pending P0441."}],deepDive:[{heading:"The code combination changes the bulletin decision",paragraphs:["Toyota's procedure first runs the automatic EVAP check. The defined branch continues when P0455 and P0441 set together, or when P0456 sets.","If P0441 appears by itself, the bulletin sends diagnosis back to the repair manual. That single sentence prevents a great deal of unnecessary cap replacement."]},{heading:"A purge fault can be mechanical without a circuit code",paragraphs:["The solenoid may click electrically while its valve leaks or its passage remains blocked. Verify actual vacuum and tank-pressure change.","Post-refuel roughness is valuable timing evidence because a leaking purge path can feed a vapor-heavy mixture into the intake."]},{heading:"Inspect modified underbodies methodically",paragraphs:["Skid plates and hitch wiring can obscure or contact rear EVAP hardware. Note fresh tool marks, pinched lines and stretched connectors.","Remove protection only with safe support and according to its installation instructions; do not begin a smoke test beside hot exhaust."]}],sources:[evapTsb,manuals,tis]}),

article({slug:"p0455",code:"P0455",title:"P0455 Code Toyota 4Runner: Locate the Large EVAP Leak",description:"Find a 4Runner P0455 with cap, valve, hose and regulated smoke tests, including Toyota's exact 2005–2009 P0455-plus-P0441 bulletin branch.",definition:"Evaporative Emission Control System Leak Detected (Gross Leak)",severity:"Service soon",driveAdvice:"A large EVAP leak usually does not disable steering or brakes, but escaping gasoline vapor is a fire hazard. Stop and park outdoors if you smell strong fuel, see wet gasoline, have a visibly damaged tank or experience refueling spit-back. Never smoke nearby or apply unregulated shop air to the tank.",quickAnswer:"P0455 means the ECM could not create or retain the pressure change expected from a sealed EVAP system. A missing cap, disconnected hose or cracked component can do that, but so can a purge or vent valve held open. Preserve the cap's found condition and recent repair/trail history, command the valves, verify tank-pressure response, then isolate sections with regulated smoke. Toyota T-SB-0030-10 covers 2005–2009 4Runners when the automatic check reproduces P0455 with P0441, or P0456; its cap/filler sealing branch is not a universal P0455 parts instruction.",symptoms:[{key:"fill",label:"Code appeared after refueling",response:"Photograph or record cap position before tightening; inspect seal and filler surface."},{key:"combo",label:"P0455 plus P0441 on 2005–2009",response:"Follow T-SB-0030-10's automatic check and cap/filler leak decision."},{key:"service",label:"Code followed tank or pump work",response:"Inspect module seals, quick-connects and vapor routing before buying parts."},{key:"impact",label:"Code followed trail contact",response:"Check rear lines, canister, brackets and wiring behind protection."}],causes:[{cause:"Fuel cap absent, loose, wrong or unable to seal",evidence:"Found loose or failed cap/filler seal test",firstTest:"Inspect and pressure-test cap/filler interface"},{cause:"Disconnected, split or pinched vapor hose",evidence:"Recent service or visible/smoke leak",firstTest:"Trace system and smoke-test"},{cause:"Vent valve stuck open",evidence:"System will not seal under command",firstTest:"Bidirectional and sealing test"},{cause:"Purge valve stuck open",evidence:"Intake vacuum present when purge is off",firstTest:"Closed-state flow test"},{cause:"Canister, tank or pump-module seal damage",evidence:"Localized smoke or pressure decay",firstTest:"Sectional isolation and visual inspection"}],freezeFrame:["Fuel level and ambient/soak temperature","Tank pressure and leak-test result","Purge and vent commands","P0441/P0456/P0446 companion codes","Recent refueling, pump or tank service","Trail impact, hitch and skid-plate work"],steps:[{title:"Preserve found condition",detail:"Do not automatically tighten or replace the cap before noting what the monitor saw."},{title:"Inspect accessible openings and routing",detail:"Check filler sealing, hoses, service connections and underbody contact."},{title:"Prove both valves can seal",detail:"Electrical command does not guarantee mechanical closure."},{title:"Smoke-test at EVAP pressure",detail:"Use approved low pressure and inspect above the tank as well as visible lines."},{title:"Check sensor plausibility",detail:"A tank-pressure PID must respond logically to controlled pressure."},{title:"Verify with Toyota utility/monitor",detail:"Meet fuel-level and temperature conditions and confirm no pending leak code."}],dontReplace:"Do not install a canister because the scanner says 'gross leak.' First prove where pressure escapes. On a matched 2005–2009 combined-code case, Toyota's procedure may lead to cap replacement only after cap/filler testing; an unmatched year or code pattern returns to ordinary diagnosis.",yearNotes:["2005–2009: T-SB-0030-10 covers a defined P0455-plus-P0441 or P0456 condition.","Older and newer leak-detection systems use different hardware and test utilities.","Fuel-pump service can disturb top-of-tank seals and vapor connections that are difficult to see from below.","Off-road armor can conceal contact damage or trap debris around EVAP components."],faqs:[{question:"Is P0455 always a gas cap?",answer:"No. A cap is one opening; valves, hoses, tank seals and canister damage can also leave the system open."},{question:"Does the Toyota bulletin apply to every P0455?",answer:"No. It specifies 2005–2009 and a particular combined-code/automatic-check result."},{question:"Can I drive?",answer:"Usually briefly if there is no odor or wet fuel; stop if a liquid leak is possible."},{question:"Can trail damage set it?",answer:"Yes. Rear EVAP parts and lines can be struck, pinched or disconnected."},{question:"Why did a new cap not fix it?",answer:"The leak may be elsewhere, the filler surface may be damaged, or the cap may be incorrect."},{question:"Can I use shop air?",answer:"Not directly. Use regulated EVAP equipment to avoid tank and valve damage."},{question:"Why has the monitor not rerun?",answer:"Fuel level, soak time, temperature and other DTCs can block enable conditions."},{question:"What proves repair?",answer:"A successful pressure/automatic EVAP check and completed monitor without pending P0455."}],deepDive:[{heading:"Large leak describes a monitor result, not a hole size you can see",paragraphs:["The system may be physically intact while a normal vent or purge passage remains open during the sealing phase. Command each valve and verify actual sealing.","A visual inspection finds disconnected lines but cannot prove a pump-module seal or cap interface holds pressure."]},{heading:"Use recent work as a map",paragraphs:["A code that starts after fuel-pump replacement, body repair, hitch wiring or skid-plate installation deserves a focused inspection of disturbed areas.","Do not assume coincidence and do not overtighten plastic fittings. Trace routing against the Toyota diagram."]},{heading:"The 2005–2009 bulletin contains a built-in stop rule",paragraphs:["The procedure uses Toyota's automatic EVAP utility to reproduce the relevant code pattern, then evaluates cap tightening and cap-to-filler sealing.","If the pattern or leak location differs, the bulletin stops applying. That prevents a useful document from becoming a parts cannon."]}],sources:[evapTsb,manuals,tis]}),

article({slug:"p0300",code:"P0300",title:"P0300 Code Toyota 4Runner: Random Misfire Diagnosis",description:"Diagnose 4Runner P0300 with cylinder counters, fuel trims, ignition, pressure and compression tests—without importing unrelated Camry or Toyota 86 bulletins.",definition:"Random/Multiple Cylinder Misfire Detected",severity:"Stop soon",driveAdvice:"A flashing check-engine light, heavy shaking or raw-fuel odor means stop sustained driving and towing; unburned fuel can destroy the catalysts. A steady lamp with smooth operation may allow a short trip for testing, but avoid high load. Shut down for mechanical knocking, low oil pressure or overheating.",quickAnswer:"P0300 means crankshaft-speed variation indicates misfire across several cylinders or without one cylinder consistently dominating. It does not mean all coils are bad. Save cylinder counters and P0301–P0308 companions at the same rpm, load and temperature as freeze frame. One cylinder calls for plug/coil/injector/compression tests; one bank suggests bank-specific air, fuel or timing; scattered cylinders on both banks suggest shared fuel pressure, MAF, purge, crank signal or mechanical causes. Toyota P0300 calibration bulletins widely found online for the 2018 Camry and 2017–2020 Toyota 86 do not list the 4Runner and must not be applied.",symptoms:[{key:"flash",label:"Lamp flashes on grade or tow",response:"Back off and stop; diagnose the active, catalyst-damaging misfire."},{key:"cold",label:"Only misfires at cold start",response:"Capture counters immediately before heat closes a leak or changes ignition demand."},{key:"idle",label:"Rough mostly at idle",response:"Check air leaks, purge flow and cylinder sealing along with ignition."},{key:"trail",label:"Fault followed water or dusty travel",response:"Inspect plug wells, connectors, intake sealing and dust tracks before swaps."}],causes:[{cause:"Worn/fouled plug, weak coil or boot tracking",evidence:"Cylinder count and controlled coil swap agree",firstTest:"Inspect labeled plugs/boots and targeted swap"},{cause:"Fuel-pressure or injector imbalance",evidence:"Lean/load pattern, pressure loss or contribution difference",firstTest:"Pressure and injector balance test"},{cause:"Unmetered air or purge fault",evidence:"Positive trims strongest at idle or post-refuel pattern",firstTest:"Smoke and purge-sealing test"},{cause:"Compression, valve or timing problem",evidence:"Persistent same-cylinder/bank pattern, noise or low compression",firstTest:"Relative compression then leak-down/timing"},{cause:"Water/dust/rodent wiring damage",evidence:"Environmental correlation or physical evidence",firstTest:"Connector, harness and intake inspection"}],freezeFrame:["Misfire counts by cylinder","RPM, load, coolant temperature and speed","Both-bank fuel trims","Fuel pressure and MAF/load data","Companion ignition, injector, correlation and lean codes","Recent water, dust, towing and service history"],steps:[{title:"Preserve the cylinder pattern",detail:"Do not clear counters or codes before recording cold/load behavior."},{title:"Classify one cylinder, one bank or shared",detail:"The distribution determines whether to test a component or a system."},{title:"Inspect environmental entry points",detail:"Check dust after the filter, water in plug wells, chewed wiring and loose grounds."},{title:"Separate ignition from fuel",detail:"Use targeted swaps and pressure/contribution tests rather than replacing sets."},{title:"Prove mechanical health",detail:"A cylinder that does not follow a coil or injector needs compression and leak-down evidence."},{title:"Repeat the original condition",detail:"Verify counters remain quiet under the temperature and load that set P0300."}],dontReplace:"Do not buy six or eight coils from P0300, and do not flash a 4Runner with a calibration from a Camry or 86 bulletin. Verify the vehicle is explicitly listed in any Toyota document. Random misfire is a detection pattern, not a component verdict.",yearNotes:["1996–2002 distributor/coil and engine architecture differs from later coil-on-plug 1GR-FE and 2UZ-FE systems.","2003–2009 V6 and V8 trucks require engine-specific cylinder numbering and bank identification.","2010–2024 1GR-FE fuel, ignition and calibration data must still be matched by VIN/year.","2025+ turbo/hybrid systems add direct-injection, boost and hybrid safety considerations."],faqs:[{question:"Can I drive with P0300?",answer:"Not with a flashing lamp, strong shaking, raw-fuel odor or major power loss."},{question:"Will new plugs fix it?",answer:"Only if inspection shows the plugs are worn, fouled, damaged or wrong for the engine."},{question:"Why is there no cylinder-specific code?",answer:"The event may be distributed or inconsistent; live counters can still reveal a leader."},{question:"Can low fuel pressure cause it?",answer:"Yes, particularly under load and often with lean or startability evidence."},{question:"Can water crossings cause misfire?",answer:"Moisture in connectors or plug wells can, but inspect and test rather than assuming."},{question:"Do Toyota's Camry/86 misfire bulletins apply?",answer:"No. Their applicability sections name those models, not the 4Runner."},{question:"Should I clear the code first?",answer:"No. Save freeze frame, counters and monitor status before losing the event context."},{question:"What confirms repair?",answer:"Stable cylinder counts through the original cold/load condition and no pending P0300."}],deepDive:[{heading:"Misfire distribution is the fastest diagnostic fork",paragraphs:["If one cylinder dominates, keep the test local until evidence moves. If both banks misfire together, shared fuel, air metering or crank information becomes more plausible.","A one-bank pattern can expose an intake seal, fuel distribution or valve-timing issue that a full coil set cannot correct."]},{heading:"Environment matters without becoming a guess",paragraphs:["Dust past an unsealed filter, water in a plug well and rodent damage under a parked trail vehicle are inspectable evidence. Document tracks, corrosion and routing.","Do not hose or chemically clean the engine before diagnosis. That can remove the failure evidence and introduce new moisture."]},{heading:"Bulletin title matches are not applicability",paragraphs:["Search results surface Toyota P0300 reprogramming documents for other models. The first page's model/year/engine table controls—not the shared code.","Use current Toyota TIS and the 4Runner VIN to check calibration. Never substitute a calibration identifier from a different platform."]}],sources:[manuals,tis]}),

article({slug:"p0016",code:"P0016",title:"P0016 Code Toyota 4Runner: Crank–Cam Correlation Diagnosis",description:"Diagnose 4Runner P0016 by checking oil/VVT response, signals and mechanical timing across 1GR-FE, 2UZ-FE and newer turbo powertrains.",definition:"Crankshaft Position–Camshaft Position Correlation (Bank 1 Sensor A)",severity:"Diagnose promptly",driveAdvice:"Stop unnecessary running if P0016 comes with timing rattle, low oil-pressure warning, stalling, severe roughness or a no-start. Mechanical timing movement can worsen suddenly. If operation is smooth, oil is full and no noise is present, limit travel to diagnosis and avoid high rpm, towing or difficult trails.",quickAnswer:"P0016 means the crankshaft and Bank 1 intake-cam signals are no longer aligned inside the ECM's permitted window. It does not prove either sensor failed. Low/wrong oil, poor oil pressure, a sticking VVT oil-control valve, damaged wiring, a moved reluctor, actuator trouble or chain/belt timing can all shift the relationship. Identify the exact engine and Bank 1, preserve commanded versus actual cam data, verify lubrication, then scope crank/cam phase. A 2UZ-FE V8 and 1GR-FE V6 do not share one timing layout, and newer turbo/hybrid engines require current information.",symptoms:[{key:"rattle",label:"Rattle on start or while running",response:"Stop repeated running and check oil pressure and mechanical timing."},{key:"instant",label:"Code resets immediately at start",response:"Capture sync/phase and verify base timing rather than waiting for a drive cycle."},{key:"after",label:"Code followed timing-cover or engine work",response:"Recheck connector identity, routing, reluctors and installed timing marks."},{key:"intermittent",label:"Code appears on steep angles or after oil service",response:"Verify oil level/grade and pressure; document operating angle and filter history."}],causes:[{cause:"Low, incorrect, aerated or degraded oil",evidence:"Level/condition wrong or pressure unstable",firstTest:"Oil verification and mechanical pressure test"},{cause:"VVT oil-control valve/circuit or restricted passage",evidence:"Command changes but actual cam response lags/sticks",firstTest:"Bidirectional response and circuit test"},{cause:"Crank/cam sensor signal or harness fault",evidence:"Dropout, noise or implausible waveform",firstTest:"Scope signals and loaded circuit test"},{cause:"Chain/belt timing or VVT actuator movement",evidence:"Persistent phase offset, noise or failed mark check",firstTest:"Engine-specific base timing verification"},{cause:"Reluctor damage or installation error",evidence:"Fault follows repair and waveform phase is wrong",firstTest:"Inspect trigger components and installation"}],freezeFrame:["Commanded and actual Bank 1 intake-cam angle","RPM, load and coolant/oil temperature","Oil level, grade, pressure and service history","Other correlation or VVT codes","Cranking synchronization and relative compression","Recent engine/timing work and off-road operating angle"],steps:[{title:"Decode Bank 1 Sensor A by engine",detail:"Sensor A generally means intake cam, but physical bank/location changes by powertrain."},{title:"Verify lubrication first",detail:"Check level on suitable ground, correct grade/condition and pressure when symptoms warrant."},{title:"Graph VVT command and response",detail:"A slow, stuck or unstable actual angle separates oil control from fixed phase offset."},{title:"Scope the relationship",detail:"Compare crank and cam signals under the condition that sets the fault."},{title:"Verify mechanical timing",detail:"Do not replace sensors when base timing or actuator position is wrong."},{title:"Perform required learn/verification",detail:"Use Toyota's engine-specific initialization and confirm cold and warm operation."}],dontReplace:"Do not replace both position sensors as a pair. They may be accurately reporting a slipped chain, VVT actuator issue or low oil pressure. Likewise, do not use a 1GR-FE timing diagram on a 2UZ-FE or newer turbo engine.",yearNotes:["The 1996–2002 3RZ/5VZ, 2003–2009 1GR/2UZ and later 1GR generations use different timing and VVT arrangements.","Bank 1 is defined by cylinder 1, not a universal driver/passenger shortcut.","Sustained steep operating angles make correct oil level particularly important but do not by themselves diagnose P0016.","2025+ turbo/hybrid systems require high-voltage awareness and current Toyota signal/timing procedures."],faqs:[{question:"Does P0016 mean a stretched chain?",answer:"It can, but oil/VVT control, wiring, sensors, actuators and reluctors must also be tested."},{question:"Can low oil set it?",answer:"Yes. VVT control depends on adequate clean oil at correct pressure."},{question:"Can I drive?",answer:"Avoid driving with rattle, low oil pressure, stalling or severe roughness; otherwise limit movement to diagnosis."},{question:"Which cam is Sensor A?",answer:"Usually the intake cam; confirm the exact Toyota engine diagram."},{question:"Should I replace the cam sensor first?",answer:"No. Check signal quality, VVT response and mechanical phase."},{question:"Can it appear after engine work?",answer:"Yes. Connector swaps, harness damage, trigger installation and timing errors become high-priority checks."},{question:"Will thicker oil fix it?",answer:"No. Use the specified grade and repair the pressure/control fault rather than masking it."},{question:"What confirms repair?",answer:"Correct phase and VVT response with no pending P0016 through cold and warm tests."}],deepDive:[{heading:"Fixed offset and slow response are different failures",paragraphs:["A cam that responds to command but stays consistently offset suggests a different problem from one that sticks and then jumps. Graph both requested and actual angle.","Combine scan data with a crank/cam waveform. The relationship helps decide whether the signal, hydraulic control or mechanical reference is wrong."]},{heading:"Check oil on appropriate ground",paragraphs:["Off-road parking angles can make a dipstick reading misleading. Recheck according to the owner's manual before diagnosing low level.","If rattle or pressure warning accompanies P0016, measure pressure with the specified method. Continued running risks more than a diagnostic code."]},{heading:"Recent work reshuffles probability",paragraphs:["After timing-cover, head or engine replacement, inspect connectors and routing before assuming normal wear. Similar plugs can reach the wrong component on some layouts.","Verify timing marks and trigger installation from engine-specific information. Paint marks and online photos are not substitutes for Toyota references."]}],sources:[manuals,tis]}),

article({slug:"p0128",code:"P0128",title:"P0128 Code Toyota 4Runner: Thermostat and Warm-Up Test",description:"Diagnose 4Runner P0128 from a true cold soak and recorded temperature curve, using Toyota 5VZ-FE and 1GR-FE monitor logic without guessing.",definition:"Coolant Thermostat (Coolant Temperature Below Thermostat Regulating Temperature)",severity:"Service soon",driveAdvice:"P0128 usually indicates slow warm-up, but watch for the opposite emergency: stop for overheating, steam, coolant loss, heater output suddenly going cold or a temperature warning. With a full cold system, stable temperature and no leak, a short data-logging drive is generally reasonable.",quickAnswer:"P0128 sets when actual coolant temperature stays below the ECM's expected regulating point after sufficient calculated warm-up. Toyota's historical 2002 5VZ-FE and 2011 1GR-FE procedures both use 75°C/167°F in their monitor descriptions, but that is diagnostic context—not permission to fit the same thermostat or procedure across every engine. Begin after an overnight soak: ECT and intake-air temperature should be close to ambient before start. Graph the full warm-up, road speed, load and fan operation. A stuck-open thermostat is common, but low coolant, trapped air, an ECT circuit biased cold, unwanted fan operation or an incorrect thermostat can imitate it.",symptoms:[{key:"heat",label:"Weak cabin heat",response:"Check coolant cold and graph warm-up; inspect for air or flow problems."},{key:"road",label:"Temperature falls at highway speed",response:"Increased airflow exposing a thermostat that cannot regulate becomes likely."},{key:"gauge",label:"Dash gauge looks normal",response:"Use scan ECT; the gauge is damped and lacks diagnostic resolution."},{key:"hot",label:"Temperature rises too high",response:"Stop and treat it as an overheating/coolant-loss problem, not a routine P0128 drive."}],causes:[{cause:"Thermostat stuck open, leaking or incorrect",evidence:"Slow rise and temperature loss with road airflow",firstTest:"Cold-start warm-up graph"},{cause:"ECT sensor/circuit biased cold",evidence:"ECT does not match IAT/ambient after soak or jumps",firstTest:"Cold-soak comparison and circuit test"},{cause:"Low coolant or trapped air",evidence:"Low cold level, recent service, unstable heater output",firstTest:"Leak/pressure check and correct bleeding"},{cause:"Cooling fan running without valid need",evidence:"Fan active cold without A/C/request",firstTest:"Compare fan command with actual operation"},{cause:"Load/temperature prerequisite fault",evidence:"Companion sensor code or implausible freeze frame",firstTest:"Resolve prerequisite data faults"}],freezeFrame:["ECT, intake-air and known ambient temperature","Time since start, rpm, load and speed","Fan command and A/C request","Coolant level and recent cooling-system work","Cabin heat behavior and outside temperature","Companion coolant, air or voltage codes"],steps:[{title:"Start after a real cold soak",detail:"Compare ECT and IAT before cranking; a large mismatch points away from the thermostat."},{title:"Inspect safely while cold",detail:"Check level, leaks, cap area and service history without opening a hot system."},{title:"Graph the entire warm-up",detail:"Record rise rate, regulation and any drop with road speed."},{title:"Check fan and heater influence",detail:"Unexpected fan operation or air pockets can remove or redirect heat."},{title:"Verify the fitted thermostat",detail:"Use the engine/VIN-correct opening specification, seal and orientation."},{title:"Repeat comparable conditions",detail:"Confirm a plausible rise and stable regulation with no pending P0128."}],dontReplace:"Do not use the 75°C monitor threshold as the thermostat's parts specification, and do not apply Camry P0128 calibration bulletins to a 4Runner. Prove sensor plausibility and the warm-up curve before opening the cooling system.",yearNotes:["Toyota's 2002 5VZ-FE procedure lists thermostat, cooling system, ECT sensor and ECM as the diagnostic areas.","The 2011 1GR-FE monitor estimates temperature from starting temperature, load and speed, then compares actual ECT.","2UZ-FE V8, 1GR-FE V6 and newer turbo powertrains require their own thermostat and bleeding procedures.","Cold weather and heater use influence warm-up but do not explain a consistently failed monitor with valid inputs."],faqs:[{question:"Is P0128 always the thermostat?",answer:"No. Sensor bias, coolant/air issues and fan operation can produce a similar warm-up result."},{question:"Can I drive?",answer:"Usually briefly if temperature is stable and coolant is full; stop for overheating or leakage."},{question:"Why does my gauge look normal?",answer:"Dash gauges are intentionally damped; scan data shows the finer temperature trend."},{question:"Is 75°C the thermostat rating?",answer:"Not necessarily. It is part of the cited monitor logic; use VIN-specific parts information."},{question:"Can winter weather cause it?",answer:"Cold conditions slow warm-up, but Toyota's monitor uses enabling logic; repeat failure still deserves testing."},{question:"Will fuel economy change?",answer:"It can, because prolonged warm-up affects fueling and emissions operation."},{question:"Can I open the radiator hot?",answer:"No. Pressurized coolant can cause severe burns; follow the cold-check procedure."},{question:"What confirms repair?",answer:"Plausible cold-soak values, normal rise/regulation and no pending P0128."}],deepDive:[{heading:"The first data point can eliminate a thermostat guess",paragraphs:["After a long soak, coolant and intake-air readings should be reasonably close to ambient. If ECT begins far colder than reality, the sensor or circuit deserves attention first.","Save exact values. A smooth sensor curve can still be offset, and the dash gauge may never reveal the bias."]},{heading:"Use airflow as a controlled clue",paragraphs:["A stuck-open thermostat may allow ECT to fall as road speed increases radiator airflow. Graph temperature, speed and load together rather than relying on heater feel.","Abort the test for low coolant, erratic temperature or overheating. Safety takes priority over completing a monitor."]},{heading:"Older Toyota logic is useful but engine-specific",paragraphs:["The 5VZ-FE and 1GR-FE references both illustrate the relationship between cold start, sufficient warm-up and measured temperature.","They do not make thermostat housings, specifications or bleeding steps interchangeable. Retrieve the procedure for the actual VIN and engine."]}],sources:[oldThermostat,currentP0128,manuals,tis]}),

article({slug:"p1604",code:"P1604",title:"P1604 Code Toyota 4Runner: Startability Diagnosis",description:"Diagnose 4Runner P1604 by classifying no-crank, slow-crank, crank/no-start and start/stall events, then testing battery, fuel, air, ignition and compression.",definition:"Startability Malfunction",severity:"Diagnose promptly",driveAdvice:"A 4Runner that stalls, repeatedly fails to start or loses fuel pressure is unreliable—move it to safety and arrange diagnosis rather than draining the battery with repeated cranking. A historical P1604 after running out of fuel or a discharged battery may not represent a current defect, but reliable restart must be verified before remote travel.",quickAnswer:"Toyota P1604 records an unsuccessful start event; it does not name the starter. Toyota's 2010 1GR-FE description includes extended cranking or engine speed falling very low shortly after start and says to check whether the vehicle ran out of fuel. Classify the event first: no crank, slow crank, normal crank/no fire, or start then stall. Save battery voltage, cranking rpm, immobilizer state, fuel pressure, MAF/throttle and companion codes during the failure. T-SB-0009-23 provides a fuel-pressure branch for specified 2014–2019 4Runners. The flex-fuel P1604 bulletin commonly found online covers 3UR-FBE Tundra/Sequoia, not the 4Runner.",symptoms:[{key:"click",label:"No crank or only a click",response:"Test battery, cables, start authorization and starter circuit before engine fueling."},{key:"slow",label:"Slow crank",response:"Measure loaded battery voltage and voltage drop; inspect mechanical drag if speed remains low."},{key:"normal",label:"Normal crank but no start",response:"Capture rpm/sync, fuel pressure, injector command and ignition evidence."},{key:"stall",label:"Starts then dies",response:"Graph the first seconds of airflow, throttle, pressure and immobilizer data."}],causes:[{cause:"Weak battery, cable resistance or starter problem",evidence:"Low cranking voltage/speed or excessive drop",firstTest:"Battery load/conductance and voltage-drop test"},{cause:"Fuel-pressure loss or empty/contaminated fuel",evidence:"Low pressure during failure, hard start or P0087",firstTest:"Measure pressure during the start event"},{cause:"Immobilizer or start-authorization fault",evidence:"Security indication or companion body/immobilizer code",firstTest:"Scan all modules and verify authorization"},{cause:"Crank signal, ignition or injector failure",evidence:"No rpm/sync, spark or injection command",firstTest:"Simultaneous cranking signal tests"},{cause:"Air, throttle, purge or mechanical compression problem",evidence:"Implausible air data, post-refuel stall or low relative compression",firstTest:"Intake/purge and relative-compression checks"}],freezeFrame:["Battery voltage and cranking rpm","Engine run time before stall","Fuel pressure during the failed event","MAF, throttle and coolant temperature","Immobilizer, crank/cam and companion codes","Fuel level, recent service and environmental conditions"],steps:[{title:"Name the failed start type",detail:"No-crank and crank/no-start are different diagnostic problems despite one customer description."},{title:"Save all-module evidence",detail:"P1604 is often secondary; companion immobilizer, fuel or signal codes may be more specific."},{title:"Test electrical cranking integrity",detail:"Measure voltage and drop under load, not with a resting battery reading alone."},{title:"Capture fuel, spark and sync together",detail:"Avoid repeated starts that let a marginal pump recover or drain the battery."},{title:"Prove air and compression",detail:"Check throttle/MAF plausibility, purge sealing and relative compression as evidence requires."},{title:"Verify hot and cold restarts",detail:"A single successful start does not prove an intermittent heat-soak or cold fault repaired."}],dontReplace:"Do not install a starter or ECM because P1604 appeared. It can be stored after empty fuel, weak battery, low pressure, immobilizer denial, missing crank signal, purge flooding or mechanical problems. Do not apply the 3UR-FBE flex-fuel Tundra/Sequoia bulletin to a 4Runner.",yearNotes:["The 2010 1GR-FE Toyota description notes both extended cranking and a start followed quickly by very low rpm/stall.","2014–2019 4Runner is listed in T-SB-0009-23's fuel-pump pressure-loss applicability.","The 3UR-FBE flex-fuel bulletin T-SB-0166-19 lists Tundra and Sequoia, not 4Runner.","Remote/off-road use makes a repeatable hot and cold restart check especially important before return to service."],faqs:[{question:"Does P1604 mean a bad starter?",answer:"No. It records a failed start event; electrical, fuel, ignition, air, authorization and mechanical causes remain possible."},{question:"Can running out of fuel set it?",answer:"Yes. Toyota's 1GR-FE description specifically says to check that history."},{question:"Can a weak battery cause it?",answer:"Yes. Low voltage and cranking speed can prevent ignition and distort other signals."},{question:"Is the fuel pump bulletin automatic coverage?",answer:"No. Verify model/VIN/VDS eligibility and demonstrate pressure loss."},{question:"Does the flex-fuel bulletin apply?",answer:"No. The cited bulletin names 3UR-FBE Tundra and Sequoia applications."},{question:"Should I keep cranking?",answer:"No. Repeated attempts drain the battery, heat the starter and can hide the original pattern."},{question:"Can P1604 be historical?",answer:"Yes. Interpret it with occurrence data, companion codes and current restart reliability."},{question:"What confirms repair?",answer:"Normal voltage, pressure and signals plus repeated hot/cold starts without a pending event code."}],deepDive:[{heading:"Classify before connecting a parts list",paragraphs:["A silent no-crank focuses attention on power, control and authorization. Normal-speed cranking with no combustion shifts the test toward sync, fuel, ignition and compression.","A start/stall event adds throttle, purge and early-run data. Record elapsed run time rather than grouping every failure under 'hard start.'"]},{heading:"Measure the pump during failure",paragraphs:["Pressure can look normal after a second attempt primes the system. Begin recording before the start request and retain the failed trace.","The 2014–2019 Toyota bulletin creates a legitimate pump branch for exact applications; it does not replace measurement or eligibility checks."]},{heading:"Prepare for remote reliability, not just one shop start",paragraphs:["Heat soak, overnight cold, low tank level and vehicle angle can expose intermittent problems. Repeat the conditions safely after repair.","Before trail use, confirm battery reserve and reliable restarts without pending codes. A vehicle that starts once in a bay is not necessarily dependable miles from assistance."]}],sources:[oldP1604,fuelTsb,manuals,tis]}),

article({slug:"p0101",code:"P0101",title:"P0101 Code Toyota 4Runner: MAF Plausibility Diagnosis",description:"Diagnose 4Runner P0101 with intake sealing, dust inspection, fuel trims and airflow/load comparisons across stock, snorkel and turbo systems.",definition:"Mass or Volume Air Flow Circuit Range/Performance",severity:"Diagnose promptly",driveAdvice:"A steady P0101 with normal operation may allow a short data-logging trip. Avoid towing and difficult trails until load calculation is trustworthy. Stop for severe hesitation, stalling, a flashing misfire lamp or turbo/engine warning because incorrect airflow information can disrupt fueling and torque control.",quickAnswer:"P0101 means MAF airflow did not agree with the ECM's expected airflow for rpm, throttle, pressure and load. It is not a direct 'replace MAF' instruction. On a 4Runner, open the air box and inspect filter seating, dust tracks downstream, flexible bellows, PCV connections and every modified intake/snorkel joint. Then compare MAF, MAP, throttle, fuel trims and calculated load at key-on/engine-off, hot idle and a controlled rpm/load point. Equal positive trims on a V engine support unmetered air or under-reporting; a large bank split suggests a bank-local problem. New turbo powertrains also require charge-air and boost-pressure checks.",symptoms:[{key:"dust",label:"Code followed dusty travel",response:"Inspect downstream dust tracks and filter/air-box sealing before cleaning the sensor."},{key:"service",label:"Code followed filter or snorkel work",response:"Recheck housing geometry, clamps, ducts, connector and forgotten hoses."},{key:"idle",label:"Rough idle with lean trims",response:"Smoke-test post-MAF, PCV and purge paths."},{key:"load",label:"Hesitation under acceleration",response:"Graph MAF/load/pressure and inspect duct collapse or charge-air leaks."}],causes:[{cause:"Post-MAF leak or loose intake connection",evidence:"Smoke outlet and positive trims",firstTest:"Full intake smoke test"},{cause:"Dust/oil contamination biases MAF",evidence:"Visible contamination or implausible flow after intake passes",firstTest:"Data comparison and approved inspection"},{cause:"MAF power, ground, signal or connector fault",evidence:"Dropout or loaded circuit failure",firstTest:"Circuit test under vibration/heat"},{cause:"Intake restriction or altered housing geometry",evidence:"Aftermarket/blocked tract and load mismatch",firstTest:"Compare with correct stock configuration/specification"},{cause:"Engine breathing, VVT or turbo-pressure fault",evidence:"Compression/cam/boost evidence",firstTest:"Engine-specific volumetric/pressure diagnosis"}],freezeFrame:["MAF airflow, MAP and calculated load","Throttle angle, rpm, speed and altitude/barometric data","Both-bank fuel trims","Coolant and intake-air temperature","Boost command/actual on turbo models","Filter, snorkel, intake modification and dusty-use history"],steps:[{title:"Do not clean away the evidence",detail:"Save airflow and trims and inspect dust tracks before touching the element."},{title:"Inspect every measured-air joint",detail:"Include air-box clips, underside bellows, resonators, PCV and snorkel adapters."},{title:"Check sensor baselines and circuit",detail:"Verify temperature/pressure plausibility and loaded power/ground integrity."},{title:"Compare several operating points",detail:"A hot-idle value alone cannot establish airflow performance under load."},{title:"Separate shared from bank-specific trim",detail:"Use V-engine bank comparison to avoid blaming one shared MAF for a localized leak."},{title:"Restore and verify",detail:"After repair/reset as specified, repeat the original load with no pending P0101."}],dontReplace:"Do not replace or spray the MAF from the code name. The sensor may be reporting correctly while a duct leaks, a filter housing restricts flow, engine breathing changes or aftermarket geometry disrupts measurement. Physical contact can permanently damage the sensing element.",yearNotes:["Third-generation 3RZ/5VZ, fourth-generation 1GR/2UZ and fifth-generation 1GR applications have different expected airflow and ducting.","Oiled filters, snorkels and aftermarket MAF housings are relevant only when inspection/data show a relationship.","Equal bank trims support a shared air-metering cause more than a one-bank split does.","2025+ turbo/hybrid systems add compressor, charge-air and pressure-sensor plausibility checks."],faqs:[{question:"Does P0101 mean the MAF is bad?",answer:"No. It means airflow is implausible; leaks, restrictions, wiring and engine breathing are also possible."},{question:"Can trail dust cause it?",answer:"Dust contamination or an unsealed filter can bias measurement and should leave inspectable evidence."},{question:"Can a snorkel cause it?",answer:"Leaks or incorrect housing geometry can, but a properly engineered sealed system is not automatically faulty."},{question:"Should I clean the MAF?",answer:"Only after preserving data and confirming contamination; use an approved method without touching the element."},{question:"Can a vacuum leak set P0101?",answer:"Yes. Air entering after the sensor is not included in measured airflow."},{question:"Can I drive?",answer:"Limit travel if it hesitates or stalls, and avoid towing or remote trails until diagnosed."},{question:"Is one grams-per-second rule universal?",answer:"No. Engine size, rpm, load, altitude and boost all change expected airflow."},{question:"What confirms repair?",answer:"Plausible MAF/load agreement, controlled trims and no pending P0101 under the original condition."}],deepDive:[{heading:"A downstream dust trail tells a story",paragraphs:["Dust on the clean side of the filter indicates a sealing problem, not merely a dirty element. Find the path at the filter edge, lid, duct or modification joint.","Clean only after documenting and correcting entry. Otherwise the MAF may contaminate again and abrasive dust continues into the engine."]},{heading:"A modified intake must preserve measurement",paragraphs:["MAF housing diameter, straight-run airflow and sensor position influence the reading. A system can be perfectly sealed yet create distorted flow at the element.","Compare against the intended configuration and calibration. Do not solve an engineering mismatch with random sensor replacement."]},{heading:"Use bank trims to challenge the MAF theory",paragraphs:["Because one MAF generally supplies both banks, similar correction supports a shared cause. A sharp one-bank difference deserves localized intake, exhaust and injector tests.","This comparison is supporting evidence, not a standalone verdict; fuel distribution and mechanical faults can complicate the pattern."]}],sources:[manuals,tis]}),

article({slug:"p0138",code:"P0138",title:"P0138 Code Toyota 4Runner: Bank 1 Sensor 2 High Voltage",description:"Diagnose 4Runner P0138 by confirming Bank 1 Sensor 2, separating rich exhaust from signal faults and rejecting non-4Runner Toyota sensor bulletins.",definition:"Oxygen Sensor Circuit High Voltage (Bank 1 Sensor 2)",severity:"Diagnose promptly",driveAdvice:"A steady P0138 with normal operation usually permits a short test drive. Stop for a flashing misfire light, smoke, strong raw-fuel odor, severe roughness or catalyst overheating. Rich combustion can damage the catalyst, while an exhaust-area harness short may worsen with heat and movement.",quickAnswer:"P0138 means the Bank 1 downstream oxygen-sensor signal remained higher than expected. It can reflect truly rich exhaust, contamination, a sensor/circuit fault, damaged exhaust wiring or connectors disturbed during repair. First confirm Bank 1 by cylinder 1 and Sensor 2 as downstream on the actual 3RZ/5VZ, 1GR or 2UZ layout. Save upstream A/F, downstream O2 and both-bank trim data, then inspect hot-zone wiring and test response under controlled mixture conditions. Toyota T-SB-0001-10 P0138 diagnostic tips list 2008–2010 Highlander and several other 2GR-FE models—but not the 4Runner. Do not import its upstream-sensor replacement branch.",symptoms:[{key:"normal",label:"MIL only",response:"Preserve freeze frame and compare both banks before clearing."},{key:"rich",label:"Fuel odor, smoke or poor economy",response:"Check trims, injectors, pressure, purge and misfire before prolonged driving."},{key:"after",label:"Code followed exhaust work",response:"Trace sensor identity, routing, pin fit and heat-shield/clip installation."},{key:"trail",label:"Code followed underbody impact",response:"Inspect sensor body, harness, connector and exhaust deformation cold."}],causes:[{cause:"Bank 1 Sensor 2 signal short or ground/reference fault",evidence:"Signal stays high during controlled electrical test",firstTest:"Loaded circuit and harness inspection"},{cause:"Actually rich exhaust",evidence:"Negative trims, odor, deposits or injector/purge evidence",firstTest:"Fuel-control diagnosis"},{cause:"Downstream sensor contaminated or failed",evidence:"Circuit passes but response remains outside specification",firstTest:"Toyota engine-specific response test"},{cause:"Connector swap or repair-routing error",evidence:"Fault began after exhaust/engine service",firstTest:"Trace part number, bank and connector"},{cause:"Impact, heat or water damage",evidence:"Physical/corrosion evidence near exhaust or underbody",firstTest:"Cold visual and circuit test"}],freezeFrame:["Bank 1 Sensor 1 A/F data","Bank 1 Sensor 2 O2 voltage","Both-bank short/long fuel trims","RPM, load, coolant temperature and speed","Misfire, rich, injector and sensor circuit codes","Exhaust work, impact and water history"],steps:[{title:"Confirm the correct bank and sensor",detail:"Bank 1 contains cylinder 1; Sensor 2 is downstream, but location changes by engine."},{title:"Determine whether the exhaust is rich",detail:"Use trims, plugs, fuel pressure, purge and injector evidence before circuit parts."},{title:"Inspect wiring in the heat zone",detail:"Check melted insulation, stretched clips, water and impact damage with exhaust cold."},{title:"Compare bank behavior",detail:"A V-engine's other bank supplies a useful control under the same operating condition."},{title:"Run a controlled response/circuit test",detail:"Prove the sensor and wiring can move through expected states."},{title:"Complete the monitor",detail:"Verify normal fuel control and no pending P0138 after repair."}],dontReplace:"Do not replace Bank 1 Sensor 2 simply because the code names its circuit, and do not apply the 2GR-FE P0138 bulletin to a 4Runner. That Toyota document's applicability excludes this model. Establish whether the exhaust is truly rich and whether the signal circuit is electrically sound.",yearNotes:["Older 3RZ-FE/5VZ-FE, 1GR-FE V6 and 2UZ-FE V8 systems require different bank and connector identification.","T-SB-0001-10 Rev1 does not list 4Runner; its special freeze-frame/upstream-sensor branch is not transferable.","Exhaust replacement, skid plates and off-road contact can change harness routing or damage clips.","2025+ turbo/hybrid sensor terminology and catalyst layout require current VIN-specific information."],faqs:[{question:"Is P0138 automatically a bad downstream O2 sensor?",answer:"No. Rich exhaust, wiring shorts, connector mistakes and contamination can produce the same high signal."},{question:"Which side is Bank 1?",answer:"The side containing cylinder 1; confirm the engine-specific Toyota diagram."},{question:"Can I drive?",answer:"Usually briefly if operation is normal, but stop for flashing misfire, smoke or raw-fuel odor."},{question:"Can a leaking injector cause it?",answer:"Yes. Excess fuel can keep oxygen low and a conventional downstream signal high."},{question:"Can purge flow cause rich exhaust?",answer:"A purge valve admitting excessive vapor can, particularly after refueling."},{question:"Does Toyota's T-SB-0001-10 apply?",answer:"No. Its listed 2GR-FE models do not include the 4Runner."},{question:"Can trail impact damage the sensor?",answer:"Yes. Inspect the sensor, wiring and pipe only after the exhaust cools."},{question:"What confirms repair?",answer:"Normal trims, correct controlled sensor response and no pending P0138."}],deepDive:[{heading:"High voltage can be chemical or electrical",paragraphs:["A rich exhaust legitimately drives a conventional downstream oxygen signal high. A short to voltage can create the same scan-tool result without rich combustion.","Fuel trims, companion codes and controlled circuit response separate those paths. Replacing the sensor before that split is guesswork."]},{heading:"The other bank is a built-in comparison",paragraphs:["On V6 and V8 trucks, compare downstream behavior and trims under identical load. A Bank 1-only electrical or exhaust issue should not necessarily appear on Bank 2.","Do not expect perfect mirrored waveforms; catalyst condition and control corrections differ. Use Toyota specifications and trends."]},{heading:"Why the popular Toyota bulletin is excluded",paragraphs:["T-SB-0001-10 contains valuable P0138 logic for specific 2GR-FE vehicles, but its applicability list does not include 4Runner.","Shared brand and code are insufficient. A 1GR-FE or 2UZ-FE truck returns to its own repair-manual procedure rather than borrowing a different engine's value window."]}],sources:[manuals,tis]}),
];
